const m = Math.max(0.1, P.m), g = Math.max(0, P.g);
const W = m * g;                          // weight = mass × gravity
// Hanging mass on a spring scale. Spring stretch ∝ weight; mass bobs gently.
const topX = w * 0.5, topY = 70;
const maxStretch = 220;
const stretch = H.clamp(W / 100 * maxStretch, 8, maxStretch);
const bob = 6 * Math.sin(t * 2);          // small oscillation, loops
const massY = topY + stretch + bob;
// ceiling
H.line(topX - 90, topY, topX + 90, topY, { color: H.colors.axis, width: 4 });
for (let i = -4; i <= 4; i++) H.line(topX + i * 20, topY, topX + i * 20 - 8, topY - 10, { color: H.colors.axis, width: 2 });
// spring coils
const coils = 10, pts = [];
for (let i = 0; i <= coils * 12; i++) {
  const f = i / (coils * 12);
  const yy = topY + f * (stretch + bob);
  const xx = topX + (i % 2 === 0 ? -14 : 14) * Math.min(1, f * coils);
  pts.push([xx, yy]);
}
H.path(pts, { color: H.colors.violet, width: 2.5 });
// mass block (size fixed — mass doesn't change)
const bs = 30 + m * 6;
H.rect(topX - bs / 2, massY, bs, bs, { fill: H.colors.accent, stroke: H.colors.bg, width: 2, radius: 6 });
H.text(m.toFixed(1) + " kg", topX, massY + bs / 2 + 5, { color: H.colors.ink, size: 13, align: "center", baseline: "middle", weight: 700 });
// weight arrow (down, scaled to W)
const wLen = H.clamp(W * 0.6, 10, 120);
